import { useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { createLandscape } from '@/viz/landscape';

export default function LandscapeVisualization({ datasets, visible, concept, colors, shapes = null }) {
  const containerRef = useRef(null);
  const navigate = useNavigate();

  useEffect(() => {
    if (!containerRef.current || datasets.length === 0) return undefined;

    const container = containerRef.current;
    const opts = { concept, colors, shapes, visible, onDatasetClick: (id) => navigate(`/datasets/${id}`) };
    let instance = createLandscape(container, datasets, opts);

    let lastWidth = container.clientWidth;
    let lastHeight = window.innerHeight;
    let frame = 0;
    const rebuild = () => {
      instance.destroy();
      instance = createLandscape(container, datasets, opts);
    };
    const schedule = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(rebuild);
    };
    const observer = new ResizeObserver(([entry]) => {
      const w = Math.round(entry.contentRect.width);
      if (w === lastWidth) return;
      lastWidth = w;
      schedule();
    });
    observer.observe(container);
    const onWindowResize = () => {
      if (window.innerHeight === lastHeight) return;
      lastHeight = window.innerHeight;
      schedule();
    };
    window.addEventListener('resize', onWindowResize);

    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
      window.removeEventListener('resize', onWindowResize);
      instance.destroy();
    };
  }, [datasets, visible, concept, colors, shapes, navigate]);

  return <div className="landscape-viz" ref={containerRef} />;
}
