import { createCsvParser } from './parseCsv.js';

export const ACCEPTED_EXTENSIONS = ['.xes', '.xes.gz', '.csv', '.csv.gz', '.yaml', '.yml', '.zip'];

const MB = 1024 * 1024;

export function isAcceptedFile(file) {
  const name = file.name.toLowerCase();
  return ACCEPTED_EXTENSIONS.some((ext) => name.endsWith(ext));
}

export function isYamlSource(file) {
  return /\.(ya?ml|zip)$/i.test(file.name);
}

export function isCsvFile(file) {
  return /\.csv(\.gz)?$/i.test(file.name);
}

function isGzip(file) {
  return file.name.toLowerCase().endsWith('.gz');
}

export function formatMB(bytes) {
  return `${Math.round(bytes / MB).toLocaleString()} MB`;
}

export async function estimatedSize(file) {
  if (!isGzip(file) || file.size < 18) return file.size;
  const tail = new DataView(await file.slice(-4).arrayBuffer());
  return Math.max(tail.getUint32(0, true), file.size);
}

function tooLarge(maxBytes) {
  return new Error(
    `the unpacked event log is larger than ${formatMB(maxBytes)}, the most this page can process in your browser`
  );
}

function progressCounter(size, onProgress) {
  let read = 0;
  let reported = -1;
  return new TransformStream({
    transform(chunk, controller) {
      read += chunk.byteLength;
      const percent = Math.floor((read / (size || 1)) * 100);
      if (percent !== reported) {
        reported = percent;
        onProgress(Math.min(1, read / (size || 1)));
      }
      controller.enqueue(chunk);
    },
  });
}

function sizeLimit(maxBytes) {
  let total = 0;
  return new TransformStream({
    transform(chunk, controller) {
      total += chunk.byteLength;
      if (total > maxBytes) controller.error(tooLarge(maxBytes));
      else controller.enqueue(chunk);
    },
  });
}

function byteStream(file, maxBytes, onProgress) {
  if (!isGzip(file) && file.size > maxBytes) throw tooLarge(maxBytes);
  if (isGzip(file) && typeof DecompressionStream === 'undefined') {
    throw new Error('This browser cannot unpack .gz files. Please unpack the file and choose the unpacked file.');
  }
  const source = onProgress ? file.stream().pipeThrough(progressCounter(file.size, onProgress)) : file.stream();
  return isGzip(file) ? source.pipeThrough(new DecompressionStream('gzip')).pipeThrough(sizeLimit(maxBytes)) : source;
}

export async function readXesFile(file, maxBytes = Infinity, onProgress = null) {
  if (!isGzip(file) && !onProgress) {
    if (file.size > maxBytes) throw tooLarge(maxBytes);
    return file.text();
  }
  return new Response(byteStream(file, maxBytes, onProgress)).text();
}

export async function readCsvFile(file, maxBytes = Infinity, onProgress = null) {
  const reader = byteStream(file, maxBytes, onProgress).pipeThrough(new TextDecoderStream()).getReader();
  const parser = createCsvParser();
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    parser.push(value);
  }
  return parser.finish();
}
