// An event log is classified along two independent dimensions:
// - Data Origin (stored as domain_context.event_log_type, Costa et al.'s "Event Log Type"): how the events came about.
// - Log Structure (basic_info.log_structure): whether the log follows one case notion or several object types.

export const REAL_LIFE = 'Real-life';
export const LAB_GENERATED = 'Lab-generated';
export const SYNTHETIC = 'Synthetic';
export const DATA_ORIGINS = [REAL_LIFE, LAB_GENERATED, SYNTHETIC];

export const CASE_CENTRIC = 'Case-centric';
export const OBJECT_CENTRIC = 'Object-centric';
export const LOG_STRUCTURES = [CASE_CENTRIC, OBJECT_CENTRIC];

const LEGACY_ORIGINS = { 'IoT Lab Logs': LAB_GENERATED, OCEL: null };

// Publication Type values that were renamed: records added before carry the old value.
const LEGACY_PUBLICATION_TYPES = { 'Open Publication': 'Standalone Dataset' };

// Records added before the split may carry "IoT Lab Logs" or "OCEL" as event log type.
export function withLogClassification(stored) {
  const publicationType = stored.academic_context?.publication_type;
  const record =
    publicationType in LEGACY_PUBLICATION_TYPES
      ? { ...stored, academic_context: { ...stored.academic_context, publication_type: LEGACY_PUBLICATION_TYPES[publicationType] } }
      : stored;
  const origin = record.domain_context?.event_log_type;
  const legacy = origin in LEGACY_ORIGINS;
  const structure = record.basic_info?.log_structure || (origin === 'OCEL' || record.log_group?.kind === 'object type' ? OBJECT_CENTRIC : CASE_CENTRIC);
  if (!legacy && record.basic_info?.log_structure === structure) return record;
  return {
    ...record,
    basic_info: { ...record.basic_info, log_structure: structure },
    domain_context: { ...record.domain_context, event_log_type: legacy ? LEGACY_ORIGINS[origin] : origin ?? null },
  };
}
