import { useEffect, useMemo, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Header from '@/components/Header';
import AttributeLexicon from '@/components/AttributeLexicon';
import { loadDatasets, loadConfig } from '@/lib/data';
import { getDomainApplication, isHidden } from '@/lib/filters';
import { setCatalogFilters } from '@/lib/catalogFilters';
import { conceptByKey, conceptValues } from '@/lib/concepts';
import { ShapeIcon, shapeMap, useShapes } from '@/lib/shapes';

function SectionText({ section, className = '' }) {
  if (!section.summary) return <p className={className}>{section.content}</p>;
  return (
    <>
      <p className={className}>{section.summary}</p>
      <details className="about-more">
        <summary>More</summary>
        <p className={className}>{section.content}</p>
      </details>
    </>
  );
}

export default function AboutPage() {
  const [datasets, setDatasets] = useState(null);
  const [config, setConfig] = useState(null);
  const navigate = useNavigate();
  const { shapes: shapesOn } = useShapes();

  useEffect(() => {
    Promise.all([loadDatasets(), loadConfig()]).then(([d, c]) => {
      setDatasets(d);
      setConfig(c);
    });
  }, []);

  const stats = useMemo(() => {
    if (!datasets) return null;
    const domainCounts = {};
    datasets.forEach((d) => {
      const domain = getDomainApplication(d);
      if (domain) domainCounts[domain] = (domainCounts[domain] || 0) + 1;
    });
    const years = datasets.map((d) => d.academic_context?.year).filter(Boolean);
    const hidden = datasets.filter(isHidden).length;
    return {
      total: datasets.length,
      listed: datasets.length - hidden,
      hidden,
      domains: Object.keys(domainCounts).length,
      domainCounts,
      yearFrom: years.length ? Math.min(...years) : null,
      yearTo: years.length ? Math.max(...years) : null,
      withFeatures: datasets.filter((d) => d.feeed_features).length,
    };
  }, [datasets]);

  const domainShapes = useMemo(
    () => (shapesOn && datasets ? shapeMap(conceptValues(conceptByKey('domain_application'), datasets)) : null),
    [shapesOn, datasets]
  );

  if (!datasets || !config) {
    return (
      <div className="main-layout">
        <div className="loading">
          <div className="loading__spinner" />
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  const about = config.about || {};
  const sections = about.sections || [];
  const navigation = config.navigation || [];
  const pathOf = (title) => navigation.find((n) => n.label === title)?.path;
  const pageSections = sections.filter((s) => !s.invite && pathOf(s.title));
  const otherSections = sections.filter((s) => !s.invite && !pathOf(s.title));
  const invites = sections.filter((s) => s.invite);
  const contactEmail = config.contribute?.email;
  const references = about.references || [];
  const openDomain = (id) => {
    setCatalogFilters({ concept: 'domain_application', values: [id], facets: {}, query: '' });
    navigate('/');
  };

  return (
    <div className="main-layout">
      <Header config={config} />
      <main className="main-content about-page">
        <header className="about-hero">
          <h1>{about.title || 'About'}</h1>
          <p className="about-page__intro">{about.introduction}</p>
        </header>

        <section className="about-block" aria-labelledby="about-glance">
          <h2 id="about-glance" className="detail-section__title">At a Glance</h2>
          <div className="about-stats">
            <div className="about-stat">
              <span className="about-stat__value">{stats.total.toLocaleString()}</span>
              <span className="about-stat__label">Event data sources indexed</span>
            </div>
            <div className="about-stat">
              <span className="about-stat__value">
                {stats.listed} <span className="about-stat__of">/ {stats.total}</span>
              </span>
              <span className="about-stat__label">Listed by name · {stats.hidden} hidden</span>
            </div>
            <div className="about-stat">
              <span className="about-stat__value">{stats.domains}</span>
              <span className="about-stat__label">Domain applications</span>
            </div>
            <div className="about-stat">
              <span className="about-stat__value">{stats.yearFrom ? `${stats.yearFrom}–${stats.yearTo}` : '—'}</span>
              <span className="about-stat__label">Academic context years</span>
            </div>
            <div className="about-stat">
              <span className="about-stat__value">
                {stats.withFeatures} <span className="about-stat__of">/ {stats.total}</span>
              </span>
              <span className="about-stat__label">With FEEED features</span>
            </div>
          </div>
        </section>

        {pageSections.length > 0 && (
          <section className="about-block" aria-labelledby="about-pages">
            <h2 id="about-pages" className="detail-section__title">Using the Site</h2>
            <div className="about-cards">
              {pageSections.map((section) => (
                <div key={section.title} className="about-card">
                  <Link to={pathOf(section.title)} className="about-card__title">
                    {section.title} →
                  </Link>
                  <SectionText section={section} className="about-card__text" />
                </div>
              ))}
            </div>
          </section>
        )}

        {invites.map((section) => (
          <section className="about-block" key={section.title} aria-label={section.title}>
            <div className="contribute-cta about-page__invite">
              <div className="contribute-cta__text">
                <h2 className="contribute-cta__title">{section.title}</h2>
                <SectionText section={section} />
                {contactEmail && (
                  <p className="about-page__contact">
                    Contact: <a href={`mailto:${contactEmail}`}>{contactEmail}</a>
                  </p>
                )}
              </div>
              <div className="contribute-cta__actions">
                <Link className="btn btn--primary btn--lg" to="/?add=1">
                  + Add Event Data
                </Link>
              </div>
            </div>
          </section>
        ))}

        {(config.domainApplications || []).length > 0 && (
          <section className="about-block" aria-labelledby="about-domains">
            <h2 id="about-domains" className="detail-section__title">Domain Applications</h2>
            <p className="about-text about-text--muted">Click a domain application to see its event datasets in the Event Data Catalog.</p>
            <div className="about-types">
              {config.domainApplications.map((d) => (
                <button
                  key={d.id}
                  type="button"
                  className="about-type"
                  style={{ '--domain-color': d.color }}
                  onClick={() => openDomain(d.id)}
                  title={`Show the event datasets of ${d.label}`}
                >
                  <span className="about-type__head">
                    {domainShapes?.[d.id] ? (
                      <span className="domain-card__swatch domain-card__swatch--shape">
                        <ShapeIcon shape={domainShapes[d.id]} color={d.color} />
                      </span>
                    ) : (
                      <span className="domain-card__swatch" />
                    )}
                    <strong>{d.label}</strong>
                    <span className="about-type__count">{(stats.domainCounts[d.id] || 0).toLocaleString()}</span>
                  </span>
                </button>
              ))}
            </div>
          </section>
        )}

        {(otherSections.length > 0 || references.length > 0) && (
          <section className="about-block" aria-labelledby="about-data">
            <h2 id="about-data" className="detail-section__title">
              {otherSections.length === 1 ? otherSections[0].title : 'Data Source'}
            </h2>
            {otherSections.map((section) => (
              <div key={section.title}>
                {otherSections.length > 1 && <h3 className="about-subtitle">{section.title}</h3>}
                <p className="about-text">{section.content}</p>
              </div>
            ))}
            {references.length > 0 && (
              <details className="about-more">
                <summary>References</summary>
                <ol className="about-page__references">
                  {references.map((ref) => (
                    <li key={ref.url || ref.text}>
                      {ref.text}{' '}
                      {ref.url && (
                        <a href={ref.url} target="_blank" rel="noopener noreferrer">
                          {ref.url}
                        </a>
                      )}
                    </li>
                  ))}
                </ol>
              </details>
            )}
          </section>
        )}

        <section className="about-block" aria-labelledby="about-lexicon">
          <h2 id="about-lexicon" className="detail-section__title">Attribute Lexicon</h2>
          <AttributeLexicon />
        </section>

        {(about.license || contactEmail) && (
          <section className="about-block" aria-labelledby="about-license">
            <h2 id="about-license" className="detail-section__title">License &amp; Contact</h2>
            {about.license && (
              <>
                <h3 className="about-subtitle">License</h3>
                <p className="about-text">
                  {about.license.text}{' '}
                  <a
                    className="about-page__license-link"
                    href={about.license.url}
                    target="_blank"
                    rel="noopener noreferrer license"
                  >
                    {about.license.fullName || about.license.name}
                  </a>
                </p>
              </>
            )}
            {contactEmail && (
              <>
                <h3 className="about-subtitle">Contact</h3>
                <p className="about-text">
                  <a className="about-page__license-link" href={`mailto:${contactEmail}`}>
                    {contactEmail}
                  </a>
                </p>
              </>
            )}
          </section>
        )}
      </main>
    </div>
  );
}
