import { useEffect, useMemo, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import Header from '@/components/Header';
import EventLogDetailContent from '@/components/EventLogDetailContent';
import SendEntriesModal from '@/components/SendEntriesModal';
import AddEventLogModal from '@/components/AddEventLogModal';
import { loadDatasets, loadConfig, getDatasetById, removeUserDataset } from '@/lib/data';
import { downloadEntry } from '@/lib/entries';
import { getDomainApplication, isHidden } from '@/lib/filters';
import { linkedLogs, perspectiveLabel } from '@/lib/linkedLogs';

export default function EventDatasetDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [datasets, setDatasets] = useState(null);
  const [config, setConfig] = useState(null);
  const [sending, setSending] = useState(false);
  const [editing, setEditing] = useState(false);

  useEffect(() => {
    Promise.all([loadDatasets(), loadConfig()]).then(([d, c]) => {
      setDatasets(d);
      setConfig(c);
    });
  }, []);

  const domainColors = useMemo(() => {
    const map = {};
    (config?.domainApplications || []).forEach((d) => {
      map[d.id] = d.color;
    });
    return map;
  }, [config]);

  if (!datasets || !config) {
    return (
      <div className="main-layout">
        <div className="loading">
          <div className="loading__spinner" />
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  const dataset = getDatasetById(datasets, id);

  if (!dataset || isHidden(dataset)) {
    return (
      <div className="main-layout">
        <Header config={config} />
        <main className="main-content">
          <div className="empty-state">
            <p>Event dataset not found.</p>
            <Link to="/" className="btn btn--secondary">← Back to the Event Data Catalog</Link>
          </div>
        </main>
      </div>
    );
  }

  return (
    <div className="main-layout">
      <Header config={config} />
      <main className="main-content">
        <Link to="/" className="btn btn--ghost log-detail__back">← Back to the Event Data Catalog</Link>
        {dataset._userAdded && (
          <div className="user-added-banner">
            <span>+ Added by you — this event dataset lives only in your browser.</span>
            <div className="user-added-banner__actions">
              <button type="button" className="btn btn--ghost btn--sm" onClick={() => setEditing(true)}>
                Edit
              </button>
              <button type="button" className="btn btn--ghost btn--sm" onClick={() => setSending(true)}>
                Send to the collection
              </button>
              <button type="button" className="btn btn--ghost btn--sm" onClick={() => downloadEntry(dataset)}>
                Download entry
              </button>
              <button
                type="button"
                className="btn btn--ghost btn--sm"
                onClick={async () => {
                  await removeUserDataset(dataset._userKey);
                  navigate('/');
                }}
              >
                Remove
              </button>
            </div>
          </div>
        )}
        {dataset.log_group && (
          <div className="linked-logs">
            <p>
              One of {dataset.log_group.size} event logs from <strong>{dataset.log_group.source}</strong>, one per{' '}
              {dataset.log_group.kind === 'process' ? 'process model' : 'case notion (object type)'}. This one has{' '}
              {perspectiveLabel(dataset.log_group)}. They count as one in the number of event data sources, and each on its own in the tiles.
            </p>
            {linkedLogs(datasets, dataset).length > 0 && (
              <ul className="linked-logs__list">
                {linkedLogs(datasets, dataset).map((d) => (
                  <li key={d._id}>
                    <Link to={`/datasets/${d._id}`}>{d.basic_info.event_log_name}</Link>
                  </li>
                ))}
              </ul>
            )}
          </div>
        )}
        <EventLogDetailContent dataset={dataset} domainColor={domainColors[getDomainApplication(dataset)]} />
      </main>
      {editing && (
        <AddEventLogModal
          config={config}
          datasets={datasets}
          editing={dataset}
          onClose={() => setEditing(false)}
          onSaved={async (saved) => {
            setDatasets(await loadDatasets());
            setEditing(false);
            if (saved && saved._id !== dataset._id) navigate(`/datasets/${saved._id}`, { replace: true });
          }}
        />
      )}
      {sending && (
        <SendEntriesModal
          config={config}
          datasets={datasets}
          initialKeys={[dataset._userKey]}
          onClose={() => setSending(false)}
          onSent={setDatasets}
        />
      )}
    </div>
  );
}
