import {
  addStoredUserDataset,
  getStoredUserDatasets,
  markStoredUserDatasetsSent,
  removeStoredUserDataset,
  updateStoredUserDataset,
} from './userDatasets';
import { slugify } from './slugify';
import { normalizeFeatureSet } from './featureSets';
import { withLogClassification } from './logClassification';
import { recomputeFeatureSelection, recomputeFeatureSpace } from './recompute';
import { forgetReviewerKey, loadReviewerBundle } from './reviewerAccess';

const BASE_PATH = import.meta.env.BASE_URL || '/';
const DATA_FILE = import.meta.env.VITE_DATA_FILE || 'event_logs.json';
const dataFile = (kind, featureSet = 'default') =>
  DATA_FILE.replace(/\.json$/, featureSet === 'default' ? `.${kind}.json` : `.${kind}.${featureSet}.json`);

let cachedCorpus = null;
let cachedDatasets = null;
let cachedConfig = null;
let cachedFeatureSpace = null;
let cachedProjectedSpace = null;
let cachedFeatureSelection = null;
let cachedSelectionView = null;

// Where the event logs come from: the anonymized public file, or, with a reviewer link, the full
// dataset decrypted from review.enc. `notice` explains why a reviewer link fell back to the public file.
let reviewerKey = null;
let sourcePromise = null;
let dataSource = { kind: 'published' };
const sourceListeners = new Set();

export function setReviewerKey(key) {
  reviewerKey = key || null;
}

export function getDataSource() {
  return dataSource;
}

/** Calls `listener` with the data source once it is known; returns the unsubscribe function. */
export function subscribeDataSource(listener) {
  sourceListeners.add(listener);
  return () => sourceListeners.delete(listener);
}

async function loadDataSource() {
  if (!sourcePromise) {
    sourcePromise = (async () => {
      if (!reviewerKey) return { kind: 'published' };
      try {
        const { records, featureSpace } = await loadReviewerBundle(reviewerKey);
        return { kind: 'published', reviewer: true, records, featureSpace };
      } catch (e) {
        forgetReviewerKey();
        return { kind: 'published', notice: `${e.message} The anonymized dataset is shown instead.` };
      }
    })().then((source) => {
      dataSource = source;
      sourceListeners.forEach((listener) => listener(source));
      return source;
    });
  }
  return sourcePromise;
}

async function fetchJson(file) {
  const res = await fetch(`${BASE_PATH}data/${file}`);
  if (!res.ok) throw new Error(`Failed to load ${file}: ${res.status}`);
  return res.json();
}

// The same event log: same name and the same size. Used to skip logs added in the browser in an earlier visit
// that are now part of the dataset.
const logSignature = (d) =>
  [d.basic_info?.event_log_name, d.basic_info?.number_of_cases, d.basic_info?.number_of_events].map(String).join('|');

// Logs added or edited during this visit are always shown, even when the dataset already has them,
// so the confirmation after adding has the log to show.
const touchedThisVisit = new Set();

function withUserDatasets(corpus) {
  const used = new Set(corpus.map((d) => d._id));
  const published = new Set(corpus.filter((d) => !d.hidden).map(logSignature));
  const added = getStoredUserDatasets()
    .filter((record) => touchedThisVisit.has(record._userKey) || !published.has(logSignature(record)))
    .map((record) => ({
      ...withLogClassification(record),
      _id: slugify(`${record.basic_info?.event_log_name || 'event log'} added`, used),
    }));
  return [...corpus, ...added];
}

export async function loadDatasets() {
  if (cachedDatasets) return cachedDatasets;
  if (!cachedCorpus) {
    const source = await loadDataSource();
    cachedCorpus = source.records || (await fetchJson(DATA_FILE));
  }
  cachedDatasets = withUserDatasets(cachedCorpus);
  return cachedDatasets;
}

export async function addUserDataset(record) {
  touchedThisVisit.add(record._userKey);
  const stored = addStoredUserDataset(record);
  cachedDatasets = null;
  cachedProjectedSpace = null;
  cachedSelectionView = null;
  const datasets = await loadDatasets();
  return { dataset: datasets.find((d) => d._userKey === record._userKey) || null, stored };
}

export async function updateUserDataset(record) {
  touchedThisVisit.add(record._userKey);
  const stored = updateStoredUserDataset(record);
  cachedDatasets = null;
  cachedProjectedSpace = null;
  cachedSelectionView = null;
  const datasets = await loadDatasets();
  return { dataset: datasets.find((d) => d._userKey === record._userKey) || null, stored };
}

export async function markUserDatasetsSent(userKeys, sent) {
  markStoredUserDatasetsSent(userKeys, sent);
  cachedDatasets = null;
  return loadDatasets();
}

export async function removeUserDataset(userKey) {
  removeStoredUserDataset(userKey);
  cachedDatasets = null;
  cachedProjectedSpace = null;
  cachedSelectionView = null;
  return loadDatasets();
}

export async function loadConfig() {
  if (cachedConfig) return cachedConfig;
  const config = await fetchJson('site.config.json');
  const overrides = Object.fromEntries(
    [
      ['githubRepo', import.meta.env.VITE_GITHUB_REPO],
    ].filter(([, value]) => value)
  );
  cachedConfig = { ...config, contribute: { ...config.contribute, ...overrides } };
  return cachedConfig;
}

export async function getFeatureSet() {
  return normalizeFeatureSet((await loadConfig()).featureSet);
}

export function projectFeatures(space, features) {
  const values = space.feature_order.map((name, i) => {
    const v = features?.[name];
    const x = v === null || v === undefined || Number.isNaN(v) ? space.imputer_mean[i] : v;
    return x * space.scaler_scale[i] + space.scaler_min[i];
  });
  const norm = Math.hypot(...values) || 1;
  const centered = values.map((v, i) => v / norm - space.pca_mean[i]);
  const dot = (loadings) => space.feature_order.reduce((s, name, i) => s + centered[i] * loadings[name], 0);
  return { PC1: dot(space.loadings_pc1), PC2: dot(space.loadings_pc2) };
}

function userPoint(d, coords) {
  return {
    id: d._id,
    log: null,
    event_log_name: d.basic_info.event_log_name,
    collection: null,
    ...coords,
    domain_application: d.domain_context?.domain_application || null,
    event_log_type: d.domain_context?.event_log_type || null,
    log_structure: d.basic_info?.log_structure || null,
    academic_context_year: d.academic_context?.year || null,
    number_of_cases: d.basic_info.number_of_cases,
    number_of_events: d.basic_info.number_of_events,
    number_of_activities: d.basic_info.number_of_activities,
    userAdded: true,
  };
}

function buildFeatureSpace(space, datasets, include) {
  const added = datasets.filter((d) => d._userAdded && d.feeed_features && (!include || include.has(d._id)));
  if (!include && !added.length) {
    return { ...space, n_user_points: 0, points: space.points };
  }
  const recomputed = recomputeFeatureSpace(space, datasets, include);
  if (recomputed) {
    const coords = new Map(recomputed.userCoords.map(({ id, ...c }) => [id, c]));
    return {
      ...recomputed,
      filtered: Boolean(include),
      n_user_points: added.length,
      points: [...recomputed.basePoints, ...added.map((d) => userPoint(d, coords.get(d._id)))],
    };
  }
  if (include) return null;
  const userPoints = added.map((d) => userPoint(d, projectFeatures(space, d.feeed_features)));
  return { ...space, n_user_points: 0, points: [...space.points, ...userPoints] };
}

export async function loadFeatureSpace(include = null) {
  if (!include && cachedProjectedSpace) return cachedProjectedSpace;
  if (!cachedFeatureSpace) {
    const featureSet = await getFeatureSet();
    const source = await loadDataSource();
    cachedFeatureSpace = source.featureSpace?.[featureSet] || (await fetchJson(dataFile('feature_space', featureSet)));
  }
  const space = buildFeatureSpace(cachedFeatureSpace, await loadDatasets(), include);
  if (!include) cachedProjectedSpace = space;
  return space;
}

// Fewest event datasets the correlations are recomputed over: a pair needs 5 shared datasets.
export const MIN_SELECTION_LOGS = 5;

/** The correlations and the greedy selection; with `include`, recomputed over those event datasets only
 * (null when fewer than MIN_SELECTION_LOGS of them have features). */
export async function loadFeatureSelection(include = null) {
  if (!include && cachedSelectionView) return cachedSelectionView;
  if (!cachedFeatureSelection) cachedFeatureSelection = await fetchJson(dataFile('feature_selection', await getFeatureSet()));
  const datasets = await loadDatasets();
  if (include) {
    const subset = datasets.filter((d) => include.has(d._id) && d.feeed_features);
    if (subset.length < MIN_SELECTION_LOGS) return null;
    return { ...recomputeFeatureSelection(cachedFeatureSelection, subset), filtered: true };
  }
  cachedSelectionView = datasets.some((d) => d._userAdded && d.feeed_features)
    ? recomputeFeatureSelection(cachedFeatureSelection, datasets)
    : cachedFeatureSelection;
  return cachedSelectionView;
}

export function getDatasetById(datasets, id) {
  return datasets.find((d) => d._id === id) || null;
}
