import { useEffect, useMemo, useState } from 'react';
import SharedFiltersBar from '@/components/SharedFiltersBar';
import { hasCatalogFilters, matchesCatalogFilters, pruneCatalogFilters, useCatalogFilters } from '@/lib/catalogFilters';
import Header from '@/components/Header';
import FeatureSpaceScatter from '@/components/FeatureSpaceScatter';
import ConceptSelect from '@/components/ConceptSelect';
import InfoTip from '@/components/InfoTip';
import { loadConfig, loadDatasets, loadFeatureSpace } from '@/lib/data';
import { humanize } from '@/lib/humanize';
import { missingStats } from '@/lib/recompute';
import { CONCEPTS, NOT_GIVEN, conceptByKey, conceptColors, conceptValue } from '@/lib/concepts';
import { ShapeIcon, ShapesToggle, shapeMap, useShapes } from '@/lib/shapes';

function pointRecord(p) {
  return {
    domain_context: { domain_application: p.domain_application, event_log_type: p.event_log_type },
    academic_context: {},
    basic_info: { log_structure: p.log_structure },
  };
}

function presentValues(points, key, minCount = 1) {
  const counts = new Map();
  points.forEach((p) => counts.set(p.concepts[key], (counts.get(p.concepts[key]) || 0) + 1));
  return [...counts.entries()]
    .filter(([, n]) => n >= minCount)
    .sort((a, b) => (a[0] === NOT_GIVEN) - (b[0] === NOT_GIVEN) || b[1] - a[1])
    .map(([v]) => v);
}

function Legend({ title, values, colors, shapes = null, outline = false }) {
  if (!values.length) return null;
  return (
    <div className="graph-legend">
      <span className="graph-legend__title">{title}</span>
      <div className="graph-legend__items">
        {values.map((v) => (
          <span className="graph-legend__item" key={v}>
            {shapes && !outline ? (
              <ShapeIcon shape={shapes[v]} color={colors[v]} />
            ) : (
              <span
                className={`graph-legend__swatch ${outline ? 'graph-legend__swatch--outline' : ''}`}
                style={outline ? { borderColor: colors[v] } : { background: colors[v] }}
              />
            )}
            {v}
          </span>
        ))}
      </div>
    </div>
  );
}

function LoadingsBar({ loadings }) {
  const entries = Object.entries(loadings)
    .sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]))
    .slice(0, 12);
  const maxAbs = Math.max(...entries.map(([, v]) => Math.abs(v)), 0.0001);

  return (
    <div className="loadings-bar">
      {entries.map(([name, value]) => (
        <div className="loadings-bar__row" key={name}>
          <span className="loadings-bar__label">{humanize(name)}</span>
          <div className="loadings-bar__track">
            <div
              className={`loadings-bar__fill ${value < 0 ? 'loadings-bar__fill--negative' : ''}`}
              style={{ width: `${(Math.abs(value) / maxAbs) * 100}%` }}
            />
          </div>
          <span className="loadings-bar__value">{value.toFixed(3)}</span>
        </div>
      ))}
    </div>
  );
}

export default function FeatureSpaceExplorationPage() {
  const [config, setConfig] = useState(null);
  const [featureSpace, setFeatureSpace] = useState(null);
  const [datasets, setDatasets] = useState(null);
  // Opens with the overview story: the colors tell what kind of data a log is, the hulls where each collection sits.
  const [colorBy, setColorBy] = useState('event_log_type');
  const [showHulls, setShowHulls] = useState(true);
  const [hullConcept, setHullConcept] = useState('data_collection');
  const [tooFew, setTooFew] = useState(false);
  const filters = useCatalogFilters();
  const filtering = hasCatalogFilters(filters);
  const hullKey = hullConcept || colorBy;
  const hullBy = showHulls ? hullKey : '';

  useEffect(() => {
    Promise.all([loadConfig(), loadDatasets()]).then(([c, d]) => {
      setConfig(c);
      setDatasets(d);
      pruneCatalogFilters(d);
    });
  }, []);

  const include = useMemo(() => {
    if (!datasets || !filtering) return null;
    return new Set(datasets.filter((d) => d.feeed_features && matchesCatalogFilters(d, filters)).map((d) => d._id));
  }, [datasets, filters, filtering]);

  useEffect(() => {
    if (!datasets) return undefined;
    let current = true;
    loadFeatureSpace(include).then((fs) => {
      if (!current) return;
      setTooFew(!fs);
      if (fs) setFeatureSpace(fs);
    });
    return () => {
      current = false;
    };
  }, [datasets, include]);

  const points = useMemo(() => {
    if (!featureSpace || !datasets) return [];
    const byId = new Map(datasets.map((d) => [d._id, d]));
    return featureSpace.points.map((p) => {
      const record = byId.get(p.id) || pointRecord(p);
      return { ...p, concepts: Object.fromEntries(CONCEPTS.map((c) => [c.key, conceptValue(c, record)])) };
    });
  }, [featureSpace, datasets]);

  const colorValues = useMemo(() => presentValues(points, colorBy), [points, colorBy]);
  const colors = useMemo(() => conceptColors(conceptByKey(colorBy), colorValues, config), [colorBy, colorValues, config]);
  const { shapes: shapesOn } = useShapes();
  const shapes = useMemo(() => (shapesOn ? shapeMap(colorValues) : null), [shapesOn, colorValues]);
  const hullValues = useMemo(() => presentValues(points, hullKey, 3).filter((v) => v !== NOT_GIVEN), [points, hullKey]);
  const hullColors = useMemo(
    () => (hullKey === colorBy ? colors : conceptColors(conceptByKey(hullKey), presentValues(points, hullKey), config)),
    [hullKey, colorBy, colors, points, config]
  );
  const missing = useMemo(
    () => (featureSpace && datasets ? missingStats(datasets, featureSpace.feature_order) : null),
    [featureSpace, datasets]
  );
  const withoutFeatures = datasets ? datasets.filter((d) => !d.feeed_features).length : 0;
  const withFeatures = datasets ? datasets.length - withoutFeatures : 0;

  if (!config || !featureSpace || !datasets) {
    return (
      <div className="main-layout">
        <div className="loading">
          <div className="loading__spinner" />
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="main-layout">
      <Header config={config} />
      <main className="main-content">
        <h1 className="t-page-title">Event Data Space</h1>
        <p className="graph-page__description">
          {withFeatures} event datasets placed by their {featureSpace.n_features} FEEED features.
          {withoutFeatures > 0 &&
            ` ${withoutFeatures} of the ${datasets.length} event datasets in the catalog ${withoutFeatures === 1 ? 'is' : 'are'} missing, as no FEEED features could be computed for ${withoutFeatures === 1 ? 'it' : 'them'}.`}{' '}
          One concept colors the points, and the same or another concept outlines each of its groups with at least 3 event
          logs. Click a point to open its event dataset.
        </p>

        <h2 className="detail-section__title feature-selection__title">
          Principal Component Analysis
          <InfoTip label="How the projection is computed">
            <span>
              Each event dataset is described by the {featureSpace.n_features} FEEED features computed for every collection.
              Each feature is min-max scaled to 0–1 so that features with large raw values don't dominate, and each log's
              vector is scaled to length 1 (L2 normalization).
            </span>
            <span>
              If a feature can't be computed for some event datasets, e.g. the skewness of the
              start activities when all cases start with the same activity, the missing value
              is replaced by the feature's mean over the event datasets that have it (mean imputation) before the scaling.
              {missing &&
                ` ${missing.withMissing} of the ${missing.features} features are missing for at least one of the ${missing.logs} event datasets, up to ${missing.maxMissing} datasets for one feature, ${(missing.share * 100).toFixed(1)} % of all values.`}{' '}
              Imputed values sit at the feature's mean, so event datasets with many of them move towards the average dataset.
              Event datasets without any FEEED features are left out.
            </span>
            <span>
              A principal component analysis (PCA) then projects the vectors onto the two directions with the most variance,
              PC1 and PC2. Their share of the variance is given on the axes.
            </span>
            <span>
              {featureSpace.n_user_points
                ? `The ${featureSpace.n_user_points} event ${featureSpace.n_user_points === 1 ? 'log' : 'logs'} you added ${featureSpace.n_user_points === 1 ? 'is' : 'are'} included: the imputation, scaling and components were recomputed in your browser, so positions and hulls can differ slightly from the published projection.`
                : 'When you add event data, it is included and the projection is recomputed in your browser.'}{' '}
              Your event datasets are marked with a dashed ring.
            </span>
          </InfoTip>
        </h2>
        <p className="graph-page__description">
          The two directions in which the event datasets differ most, so that datasets close to each other have similar features.
          {featureSpace.n_user_points
            ? ` Recomputed with your ${featureSpace.n_user_points} added event ${featureSpace.n_user_points === 1 ? 'log' : 'logs'}.`
            : ''}
        </p>

        <section className="landscape-section">
          <div className="concept-controls">
            <ConceptSelect id="fs-concept" label="Colors" value={colorBy} onChange={setColorBy} />
            <label className="add-log__check concept-controls__check">
              <input type="checkbox" checked={showHulls} onChange={(e) => setShowHulls(e.target.checked)} />
              <span>Convex hulls</span>
            </label>
            {showHulls && <ConceptSelect id="fs-hull-concept" label="Hulls" value={hullKey} onChange={setHullConcept} />}
            <ShapesToggle />
          </div>
          <SharedFiltersBar
            datasets={datasets}
            summary={
              tooFew
                ? 'Fewer than 3 event datasets match the filters, so the plot shows the last result.'
                : filtering
                  ? `PCA recomputed over the ${include?.size ?? featureSpace.n_points} of ${withFeatures} event datasets that match the filters.`
                  : `PCA over all ${withFeatures} event datasets.`
            }
          />
          <FeatureSpaceScatter
            points={points}
            colorBy={colorBy}
            colors={colors}
            shapes={shapes}
            hullBy={hullBy}
            hullColors={hullColors}
            explainedVariance={featureSpace.explained_variance_ratio}
          />
          <Legend title={conceptByKey(colorBy).label} values={colorValues} colors={colors} shapes={shapes} />
          {showHulls && hullKey !== colorBy && (
            <Legend title={`Hulls: ${conceptByKey(hullKey).label}`} values={hullValues} colors={hullColors} outline />
          )}
        </section>

        <div className="loadings-pair">
          <section className="detail-section">
            <h2 className="detail-section__title feature-selection__title">
              Top Features Driving PC1
              <InfoTip label="What the loadings show">
                <span>
                  The 12 features with the largest weights (loadings) in the component. A long bar means the feature moves
                  event datasets strongly along the axis. Positive and negative weights push in opposite directions.
                </span>
              </InfoTip>
            </h2>
            <LoadingsBar loadings={featureSpace.loadings_pc1} />
          </section>
          <section className="detail-section">
            <h2 className="detail-section__title">Top Features Driving PC2</h2>
            <LoadingsBar loadings={featureSpace.loadings_pc2} />
          </section>
        </div>
      </main>
    </div>
  );
}
