export const groupKey = (d) => d.log_group?.id || d._id;

export function independentDatasets(datasets) {
  const seen = new Set();
  return datasets.filter((d) => {
    const key = groupKey(d);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

export function linkedLogs(datasets, dataset) {
  if (!dataset.log_group) return [];
  return datasets.filter((d) => d !== dataset && d.log_group?.id === dataset.log_group.id);
}

export function perspectiveLabel(group) {
  return `${group.kind === 'process' ? 'process' : 'case'}: ${group.perspective}`;
}
