import yaml from 'js-yaml';
import { parseTimeMicros } from './parseXes.js';

const UNSPECIFIED = '__NOTSPECIFIED__';
const UNNAMED_PROCESS = 'Unnamed process';

export function isXesYamlName(name) {
  return /\.xes\.ya?ml$/i.test(name);
}

const given = (v) => v !== null && v !== undefined && v !== '' && v !== UNSPECIFIED;

function scalar(v) {
  if (v instanceof Date) return v.toISOString();
  return v !== null && typeof v === 'object' ? undefined : v;
}

// CPEE names some instances after the object they handle, e.g. "Wellplate: 567" or "Sample: <uuid>".
// The process model is the name without that suffix, so all such instances form one event log.
const INSTANCE_SUFFIX = /^(.*\S)\s*:\s*[\w-]*\d[\w-]*$/;

export function processModelName(name) {
  return INSTANCE_SUFFIX.exec(name)?.[1] ?? name;
}

export function parseXesYamlText(text, fileName = '') {
  let header = null;
  const cases = new Map();
  let total = 0;
  yaml.loadAll(
    text,
    (doc) => {
      if (!doc || typeof doc !== 'object') return;
      if (doc.log) {
        header = doc.log;
        return;
      }
      const ev = doc.event;
      if (!ev || typeof ev !== 'object') return;
      total += 1;
      const name = ev['concept:name'];
      if (!given(name)) return;
      const instance = String(ev['concept:instance'] ?? header?.trace?.['concept:name'] ?? fileName);
      const attributes = {};
      Object.entries(ev).forEach(([k, v]) => {
        const s = scalar(v);
        if (s !== undefined) attributes[k] = s;
      });
      const rawTime = scalar(ev['time:timestamp']);
      const timeMicros = parseTimeMicros(rawTime);
      if (!cases.has(instance)) cases.set(instance, []);
      cases.get(instance).push({
        activity: String(name),
        timestamp: timeMicros === null ? null : new Date(timeMicros / 1000),
        timeMicros,
        resource: given(ev['org:resource']) ? String(ev['org:resource']) : null,
        attributes,
        lifecycle: String(ev['lifecycle:transition'] ?? ''),
      });
    },
    { schema: yaml.CORE_SCHEMA }
  );
  if (!header && !total) throw new Error(`${fileName || 'This file'} is not an XES YAML file.`);
  const trace = header?.trace || {};
  const process = trace['cpee:name'] !== undefined ? processModelName(String(trace['cpee:name'])) : String(trace['concept:name'] ?? UNNAMED_PROCESS);
  const traces = [...cases.entries()].map(([caseId, events]) => ({
    caseId,
    process,
    attributes: Object.fromEntries(Object.entries(trace).map(([k, v]) => [k, scalar(v)]).filter(([, v]) => v !== undefined)),
    events,
  }));
  return { traces, process, totalEvents: total };
}

function byTime(a, b) {
  if (a.timeMicros === null || b.timeMicros === null) return 0;
  return a.timeMicros - b.timeMicros;
}

export function xesYamlLogs(traces, { split = true, include = null } = {}) {
  const chosen = traces.filter((t) => !include || include.has(t.process));
  const named = chosen.reduce((s, t) => s + t.events.length, 0);
  const onlyComplete = chosen.some((t) => t.events.some((e) => e.lifecycle === 'complete'));
  const groups = new Map();
  chosen.forEach((t) => {
    const key = split ? t.process : '';
    const events = (onlyComplete ? t.events.filter((e) => e.lifecycle === 'complete') : t.events)
      .map(({ lifecycle: _lifecycle, ...e }) => e)
      .sort(byTime);
    if (!events.length) return;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push({ caseId: t.caseId, attributes: { ...t.attributes, 'concept:name': t.caseId }, events });
  });
  const logs = [...groups.entries()].map(([process, list]) => ({
    process,
    traces: list.sort((a, b) => byTime(a.events[0], b.events[0])),
  }));
  const kept = logs.reduce((s, l) => s + l.traces.reduce((n, t) => n + t.events.length, 0), 0);
  const assumptions =
    onlyComplete && kept < named
      ? [
          {
            group: 'XES YAML',
            text: `Only the events that complete an activity (lifecycle "complete") are kept, ${kept.toLocaleString()} of ${named.toLocaleString()} named events. Calls, received messages, data and state changes are left out.`,
          },
        ]
      : [];
  return { logs, assumptions };
}

export function processSummary(traces) {
  const counts = new Map();
  traces.forEach((t) => {
    const c = counts.get(t.process) || { process: t.process, cases: 0, events: 0 };
    c.cases += 1;
    c.events += t.events.length;
    counts.set(t.process, c);
  });
  return [...counts.values()].sort((a, b) => b.cases - a.cases);
}
