import * as d3 from 'd3';
import { isHidden } from '@/lib/filters';
import { escapeHtml } from '@/lib/humanize';
import { conceptValue } from '@/lib/concepts';
import { shapePath } from '@/lib/shapes';

function stableUnit(text) {
  let h = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0) / 4294967296;
}

export function createLandscape(container, datasets, { concept, colors, shapes = null, visible, onDatasetClick } = {}) {
  const width = container.clientWidth || 900;

  const years = datasets.map((d) => d.academic_context?.year).filter(Boolean);
  const yearExtent = d3.extent(years);
  const yearDomain = yearExtent[0] === yearExtent[1] ? [yearExtent[0] - 1, yearExtent[0] + 1] : yearExtent;

  const domainCounts = new Map();
  datasets.forEach((d) => {
    const value = conceptValue(concept, d);
    domainCounts.set(value, (domainCounts.get(value) || 0) + 1);
  });
  // When filtering, only the categories that still hold a shown event log keep a row; the order stays that of all logs.
  const shownValues = visible ? new Set(datasets.filter((d) => visible.has(d._id)).map((d) => conceptValue(concept, d))) : null;
  const domains = [...domainCounts.entries()]
    .sort((a, b) => (b[0] === 'Not given') - (a[0] === 'Not given') || b[1] - a[1])
    .map(([value]) => value)
    .filter((value) => !shownValues || shownValues.has(value));

  const fontSize = width < 500 ? 12 : 14;
  const margin = { top: 20, right: 20, bottom: 2 * fontSize + 34, left: 0 };

  // About 38% of the visible window and at most 38% as tall as wide; grows only when the rows need it.
  const rowMin = fontSize + 4;
  const byRows = margin.top + margin.bottom + domains.length * rowMin;
  const header = document.querySelector('.app-header')?.offsetHeight || 0;
  const byWindow = ((window.innerHeight || 800) - header) * 0.38;
  const height = Math.round(Math.max(byRows, 200, Math.min(byWindow, width * 0.38)));

  const y = d3.scaleBand().domain(domains).range([height - margin.bottom, margin.top]).paddingOuter(0.5);

  const maxRadius = Math.max(7, Math.min(16, width / 100, y.bandwidth() * 0.6));
  const caseExtent = d3.extent(datasets, (d) => d.basic_info?.number_of_cases || 0);
  const radiusScale = d3.scaleSqrt().domain([0, caseExtent[1] || 1]).range([3, maxRadius]).clamp(true);

  const svg = d3
    .select(container)
    .append('svg')
    .attr('width', width)
    .attr('height', height)
    .attr('viewBox', [0, 0, width, height]);

  const maxLabel = width * (width < 500 ? 0.38 : 0.28);
  const yAxis = svg
    .append('g')
    .call(d3.axisLeft(y).tickSize(0).tickPadding(10))
    .call((g) => g.selectAll('text').attr('fill', 'var(--text-muted)').attr('font-size', fontSize))
    .call((g) => g.selectAll('line,path').attr('stroke', 'var(--border)'));
  yAxis.selectAll('.tick text').each(function shorten(value) {
    const label = d3.select(this);
    if (this.getComputedTextLength() <= maxLabel) return;
    let text = String(value);
    while (text.length > 1 && this.getComputedTextLength() > maxLabel) {
      text = text.slice(0, -1);
      label.text(`${text.trimEnd()}…`);
    }
    label.append('title').text(value);
  });
  const labelWidth = d3.max(yAxis.selectAll('text').nodes(), (node) => node.getBBox().width) || 0;
  margin.left = Math.ceil(labelWidth) + 14;
  yAxis.attr('transform', `translate(${margin.left},0)`);

  const x = d3
    .scaleLinear()
    .domain([yearDomain[0] - 0.5, yearDomain[1] + 0.5])
    .range([margin.left + maxRadius + 6, width - margin.right - maxRadius]);

  const span = yearDomain[1] - yearDomain[0] + 1;
  const step = Math.max(1, Math.ceil(span / Math.max(2, Math.floor((width - margin.left) / (fontSize * 4.5)))));
  const yearTicks = d3.range(yearDomain[0], yearDomain[1] + 1).filter((year) => (year - yearDomain[0]) % step === 0);

  svg
    .append('g')
    .attr('transform', `translate(0,${height - margin.bottom})`)
    .call(d3.axisBottom(x).tickFormat(d3.format('d')).tickValues(yearTicks))
    .call((g) => g.selectAll('text').attr('fill', 'var(--text-muted)').attr('font-size', fontSize))
    .call((g) => g.selectAll('line,path').attr('stroke', 'var(--border)'))
    .call((g) => g.select('.domain').attr('d', `M${margin.left},0.5H${width - margin.right}`));

  svg
    .append('text')
    .attr('x', (margin.left + width - margin.right) / 2)
    .attr('y', height - 8)
    .attr('text-anchor', 'middle')
    .attr('fill', 'var(--text-muted)')
    .attr('font-size', fontSize)
    .text('Publication Year');

  const jitterY = (d) => (stableUnit(String(d._id)) - 0.5) * y.bandwidth() * 0.7;

  const rows = new Set(domains);
  const points = datasets
    .filter((d) => d.academic_context?.year && rows.has(conceptValue(concept, d)))
    .map((d) => {
      const domain = conceptValue(concept, d);
      return {
        dataset: d,
        x: d.academic_context.year,
        y: y(domain) + y.bandwidth() / 2 + jitterY(d),
        value: domain,
        color: colors[domain] || '#88c0d0',
        shape: shapes?.[domain] || 'circle',
        radius: radiusScale(d.basic_info?.number_of_cases || 0),
        hidden: isHidden(d),
        userAdded: Boolean(d._userAdded),
        shown: !visible || visible.has(d._id),
      };
    });

  const tooltip = d3.select(container).append('div').attr('class', 'landscape-tooltip').style('opacity', 0);

  const pointsLayer = svg.append('g');

  pointsLayer
    .selectAll('circle.user-added-ring')
    .data(points.filter((d) => d.userAdded))
    .join('circle')
    .attr('class', 'user-added-ring')
    .attr('cx', (d) => x(d.x))
    .attr('cy', (d) => d.y)
    .attr('r', (d) => d.radius + 4)
    .attr('fill', 'none')
    .attr('stroke', 'var(--accent)')
    .attr('stroke-width', 1.5)
    .attr('stroke-dasharray', '3,2')
    .style('display', (d) => (d.shown ? null : 'none'))
    .style('pointer-events', 'none');

  const circles = pointsLayer
    .selectAll('path.landscape-point')
    .data([...points].sort((a, b) => b.hidden - a.hidden))
    .join('path')
    .attr('class', 'landscape-point')
    .attr('transform', (d) => `translate(${x(d.x)},${d.y})`)
    .attr('d', (d) => shapePath(d.shape, d.radius))
    .attr('fill', (d) => d.color)
    .attr('fill-opacity', (d) => (d.hidden ? 0.28 : 0.75))
    .attr('stroke', (d) => (d.hidden ? 'var(--bg)' : 'var(--text)'))
    .attr('stroke-width', 1)
    .style('display', (d) => (d.shown ? null : 'none'))
    .style('cursor', (d) => (d.hidden ? 'default' : 'pointer'))
    .on('mouseenter', (event, d) => {
      if (d.hidden) return;
      const cases = d.dataset.basic_info?.number_of_cases;
      tooltip
        .style('opacity', 1)
        .html(
          `<strong>${escapeHtml(d.dataset.basic_info.event_log_name)}</strong>` +
            (d.userAdded ? ' <span style="color:var(--accent-text)">· Added by you</span>' : '') +
            `<br/>${d.x} · ${escapeHtml(d.value)}` +
            (cases ? `<br/>${cases.toLocaleString()} cases` : '')
        );
    })
    .on('mousemove', (event) => {
      const [mx, my] = d3.pointer(event, container);
      const tooltipWidth = tooltip.node().offsetWidth;
      const overflowsRight = mx + 12 + tooltipWidth > container.clientWidth;
      const left = overflowsRight ? mx - 12 - tooltipWidth : mx + 12;
      tooltip.style('left', `${left}px`).style('top', `${my + 12}px`);
    })
    .on('mouseleave', () => tooltip.style('opacity', 0))
    .on('click', (event, d) => {
      if (!d.hidden && onDatasetClick) onDatasetClick(d.dataset._id);
    });

  return {
    destroy: () => {
      circles.interrupt();
      tooltip.remove();
      svg.remove();
    },
  };
}
