import { useSyncExternalStore } from 'react';
import { CONCEPTS, conceptByKey, conceptValue } from '@/lib/concepts';
import { FACETS, getFacetOptions, matchesFacetFilters } from '@/lib/filters';

const STORAGE_KEY = 'xespresso:catalog-filters';
const EMPTY = { concept: 'domain_application', values: [], facets: {}, query: '' };

function load() {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    const stored = raw ? { ...EMPTY, ...JSON.parse(raw) } : EMPTY;
    const facets = Object.fromEntries(Object.entries(stored.facets || {}).filter(([key]) => FACETS.some((f) => f.key === key)));
    const known = CONCEPTS.some((c) => c.key === stored.concept);
    return { ...stored, facets, ...(known ? {} : { concept: EMPTY.concept, values: [] }) };
  } catch {
    return EMPTY;
  }
}

let state = load();
const listeners = new Set();

function save() {
  try {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    return false;
  }
  return true;
}

export function setCatalogFilters(update) {
  state = { ...state, ...(typeof update === 'function' ? update(state) : update) };
  save();
  listeners.forEach((l) => l());
}

function subscribe(listener) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function useCatalogFilters() {
  return useSyncExternalStore(subscribe, () => state);
}

export function pruneCatalogFilters(datasets) {
  if (!datasets?.length) return;
  const concept = conceptByKey(state.concept);
  const present = new Set(datasets.map((d) => conceptValue(concept, d)));
  const values = state.values.filter((v) => present.has(v));
  let changed = values.length !== state.values.length;
  const facets = Object.fromEntries(
    Object.entries(state.facets).map(([key, selected]) => {
      const facet = FACETS.find((f) => f.key === key);
      if (!facet || !selected?.length) return [key, selected];
      const options = new Set(getFacetOptions(datasets, facet).map((o) => o.value));
      const kept = selected.filter((v) => options.has(v));
      if (kept.length !== selected.length) changed = true;
      return [key, kept];
    })
  );
  if (changed) setCatalogFilters({ values, facets });
}

export function hasConceptFilters(filters) {
  return filters.values.length > 0 || Object.values(filters.facets).some((v) => v && v.length > 0);
}

export function matchesConceptFilters(dataset, filters) {
  const concept = conceptByKey(filters.concept);
  if (filters.values.length > 0 && !filters.values.includes(conceptValue(concept, dataset))) return false;
  return matchesFacetFilters(dataset, filters.facets);
}

export function matchesQuery(dataset, query) {
  const q = (query || '').trim().toLowerCase();
  if (!q) return true;
  return [
    dataset.basic_info?.event_log_name,
    dataset.domain_context?.domain_application,
    dataset.domain_context?.process_information,
    dataset.academic_context?.reference,
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase()
    .includes(q);
}

// The filters every page applies: the concept tiles, the facets and the search, set on any page.
export function hasCatalogFilters(filters) {
  return hasConceptFilters(filters) || Boolean((filters.query || '').trim());
}

export function matchesCatalogFilters(dataset, filters) {
  return matchesConceptFilters(dataset, filters) && matchesQuery(dataset, filters.query);
}

export function clearCatalogFilters() {
  setCatalogFilters({ values: [], facets: {}, query: '' });
}
