import { NOT_GIVEN } from '@/lib/concepts';

const present = (v) => (v === null || v === undefined || v === '' ? [] : [v]);

export function isHidden(record) {
  return Boolean(record.hidden);
}

export function getDomainApplication(record) {
  return record.domain_context?.domain_application || null;
}

export const FACETS = [
  {
    key: 'domain_application',
    label: 'Domain Application',
    getValues: (r) => present(r.domain_context?.domain_application),
  },
  {
    key: 'event_log_type',
    label: 'Data Origin',
    getValues: (r) => present(r.domain_context?.event_log_type),
  },
  {
    key: 'log_structure',
    label: 'Log Structure',
    getValues: (r) => present(r.basic_info?.log_structure),
  },
  {
    key: 'process_type',
    label: 'Process Type',
    getValues: (r) => present(r.domain_context?.process_type),
  },
  {
    key: 'publication_type',
    label: 'Publication Type',
    getValues: (r) => present(r.academic_context?.publication_type),
  },
  {
    key: 'data_collection',
    label: 'Data Collection',
    getValues: (r) => present(r.data_collection),
  },
  {
    key: 'dataset_format',
    label: 'Dataset Format',
    getValues: (r) => present(r.basic_info?.dataset_format),
  },
  {
    key: 'resource_availability',
    label: 'Resource Availability',
    getValues: (r) => present(r.basic_info?.resource_availability).map((v) => (v ? 'Yes' : 'No')),
  },
  {
    key: 'feeed_available',
    label: 'FEEED Features',
    getValues: (r) => [r.feeed_available ? 'Computed' : 'Not computed'],
  },
];

const facetValues = (facet, record) => {
  const values = facet.getValues(record);
  return values.length ? values : [NOT_GIVEN];
};

export function getFacetOptions(records, facet) {
  const counts = {};
  records.forEach((r) => {
    facetValues(facet, r).forEach((v) => {
      counts[v] = (counts[v] || 0) + 1;
    });
  });
  return Object.entries(counts)
    .sort((a, b) => (a[0] === NOT_GIVEN) - (b[0] === NOT_GIVEN) || b[1] - a[1])
    .map(([value, count]) => ({ value, count }));
}

export function facetGivenCount(records, facet) {
  return records.filter((r) => facet.getValues(r).length > 0).length;
}

export function matchesFacetFilters(record, facetFilters) {
  return FACETS.every((facet) => {
    const selected = facetFilters[facet.key];
    if (!selected || selected.length === 0) return true;
    const values = facetValues(facet, record);
    return selected.some((v) => values.includes(v));
  });
}
