import { useMemo, useState } from 'react';
import { LEXICON, LEXICON_SOURCES, LEXICON_STATUS } from '@/lib/lexicon';

const matches = (e, q) => [e.name, e.key, e.meaning, e.costa || ''].some((t) => t.toLowerCase().includes(q));

export default function AttributeLexicon() {
  const [query, setQuery] = useState('');
  const q = query.trim().toLowerCase();
  const groups = useMemo(
    () => LEXICON.map((g) => ({ ...g, shown: q ? g.entries.filter((e) => matches(e, q)) : g.entries })).filter((g) => g.shown.length),
    [q]
  );
  const total = LEXICON.reduce((n, g) => n + g.entries.length, 0);

  return (
    <>
      <p className="about-text">
        What each attribute of an event dataset means in XESpresso. Most come from the metadata structure by Costa et al., some were
        renamed, extended or added. The tag says which.
      </p>
      <ul className="lexicon__legend">
        {Object.entries(LEXICON_STATUS).map(([id, s]) => (
          <li key={id}>
            <span className={`lexicon__tag lexicon__tag--${id}`}>{s.label}</span> {s.text}
          </li>
        ))}
      </ul>
      <details className="about-more">
        <summary>Sources</summary>
        <ul className="lexicon__sources">
          <li>{LEXICON_SOURCES.paper}</li>
          <li>{LEXICON_SOURCES.table}</li>
        </ul>
      </details>
      <input
        type="search"
        className="lexicon__search"
        placeholder={`Search ${total} attributes…`}
        aria-label="Search the attributes"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      {groups.length === 0 && <p className="about-text about-text--muted">No attribute matches "{query}".</p>}
      {groups.map((g) => (
        <details key={g.group} className="lexicon__group" open={Boolean(q)}>
          <summary>
            <span className="lexicon__group-title">{g.group}</span>
            <span className="lexicon__count">
              {q ? `${g.shown.length} of ${g.entries.length}` : g.entries.length} attribute{g.entries.length === 1 ? '' : 's'}
            </span>
          </summary>
          {g.costa && <p className="lexicon__group-note">{g.costa}</p>}
          <dl className="lexicon__list">
            {g.shown.map((e) => (
              <div key={e.name} className="lexicon__entry">
                <dt>
                  <span className="lexicon__name">{e.name}</span>
                  <span className={`lexicon__tag lexicon__tag--${e.status}`}>{LEXICON_STATUS[e.status].label}</span>
                  <code className="lexicon__key">{e.key}</code>
                </dt>
                <dd>
                  <p>{e.meaning}</p>
                  {e.costa && <p className="lexicon__costa">{e.costa}</p>}
                </dd>
              </div>
            ))}
          </dl>
        </details>
      ))}
    </>
  );
}
