import { useEffect, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { getDataSource, subscribeDataSource } from '@/lib/data';
import ThemeToggle from './ThemeToggle';

function ReviewerBanner() {
  const [source, setSource] = useState(getDataSource);
  useEffect(() => subscribeDataSource(setSource), []);
  if (source.reviewer) {
    return (
      <div className="reviewer-banner" role="status">
        Reviewer access: the full dataset is shown. Please do not share the link.
      </div>
    );
  }
  if (source.notice) {
    return (
      <div className="reviewer-banner reviewer-banner--notice" role="alert">
        {source.notice}
      </div>
    );
  }
  return null;
}

export default function Header({ config }) {
  const location = useLocation();
  const site = config?.site || {};
  const nav = config?.navigation || [];

  return (
    <>
    <header className="app-header">
      <Link to="/" className="app-header__brand">
        <img className="app-header__logo" src={`${import.meta.env.BASE_URL}logo.svg`} alt="" width="44" height="44" />
        <span className="app-header__titles">
          <span className="app-header__title">{site.title || 'XESpresso'}</span>
          {site.subtitle && <span className="app-header__subtitle">{site.subtitle}</span>}
        </span>
      </Link>

      <nav className="app-header__nav">
        {nav.map((item) => (
          <Link
            key={item.path}
            to={item.path}
            className={`app-header__link ${location.pathname === item.path ? 'app-header__link--active' : ''}`}
          >
            {item.label}
          </Link>
        ))}
      </nav>

      <ThemeToggle />
    </header>
    <ReviewerBanner />
    </>
  );
}
