import { useId, useRef } from 'react';

const EDGE = 12;

function visibleFrame(el) {
  for (let node = el.parentElement; node && node !== document.body; node = node.parentElement) {
    const style = getComputedStyle(node);
    if (/(auto|scroll|hidden|clip)/.test(`${style.overflowX} ${style.overflowY}`)) {
      const rect = node.getBoundingClientRect();
      const left = rect.left + node.clientLeft;
      return { left, right: left + node.clientWidth };
    }
  }
  return { left: 0, right: document.documentElement.clientWidth };
}

export default function InfoTip({ label = 'More information', children }) {
  const id = useId();
  const bubbleRef = useRef(null);

  const place = () => {
    const bubble = bubbleRef.current;
    if (!bubble) return;
    bubble.style.setProperty('--tip-shift', '0px');
    bubble.style.removeProperty('width');
    requestAnimationFrame(() => {
      let rect = bubble.getBoundingClientRect();
      if (!rect.width) return;
      const frame = visibleFrame(bubble);
      const room = frame.right - frame.left - 2 * EDGE;
      if (rect.width > room) {
        bubble.style.width = `${Math.max(room, 160)}px`;
        rect = bubble.getBoundingClientRect();
      }
      let shift = 0;
      if (rect.right > frame.right - EDGE) shift = frame.right - EDGE - rect.right;
      if (rect.left + shift < frame.left + EDGE) shift = frame.left + EDGE - rect.left;
      bubble.style.setProperty('--tip-shift', `${Math.round(shift)}px`);
    });
  };

  return (
    <span className="info-tip" onMouseEnter={place} onFocus={place}>
      <button type="button" className="info-tip__button" aria-label={label} aria-describedby={id}>
        i
      </button>
      <span role="tooltip" id={id} className="info-tip__bubble" ref={bubbleRef}>
        {children}
      </span>
    </span>
  );
}
