import { useCallback, useEffect, useMemo, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import Header from '@/components/Header';
import DomainApplicationsOverview from '@/components/DomainApplicationsOverview';
import EventLogCard from '@/components/EventLogCard';
import FiltersPanel from '@/components/FiltersPanel';
import StatsBar from '@/components/StatsBar';
import LandscapeVisualization from '@/components/LandscapeVisualization';
import AddEventLogModal from '@/components/AddEventLogModal';
import SendEntriesModal from '@/components/SendEntriesModal';
import ConceptSelect from '@/components/ConceptSelect';
import { loadDatasets, loadConfig } from '@/lib/data';
import { isHidden, matchesFacetFilters } from '@/lib/filters';
import {
  clearCatalogFilters,
  matchesCatalogFilters,
  matchesQuery,
  pruneCatalogFilters,
  setCatalogFilters,
  useCatalogFilters,
} from '@/lib/catalogFilters';
import { conceptByKey, conceptColors, conceptValue, conceptValues } from '@/lib/concepts';
import { ShapesToggle, shapeMap, useShapes } from '@/lib/shapes';

export default function EventDatasetsPage() {
  const [datasets, setDatasets] = useState(null);
  const [config, setConfig] = useState(null);
  const catalogFilters = useCatalogFilters();
  const { concept: landscapeConcept, values: selectedValues, facets: facetFilters, query } = catalogFilters;
  const setQuery = (q) => setCatalogFilters({ query: q });
  const [showFilters, setShowFilters] = useState(false);
  const [searchParams, setSearchParams] = useSearchParams();
  const [showAddLog, setShowAddLog] = useState(() => searchParams.has('add'));
  const [sendKeys, setSendKeys] = useState(null);

  useEffect(() => {
    if (!searchParams.has('add')) return;
    const next = new URLSearchParams(searchParams);
    next.delete('add');
    setSearchParams(next, { replace: true });
  }, [searchParams, setSearchParams]);

  useEffect(() => {
    Promise.all([loadDatasets(), loadConfig()]).then(([d, c]) => {
      setDatasets(d);
      setConfig(c);
    });
  }, []);

  useEffect(() => {
    pruneCatalogFilters(datasets);
  }, [datasets]);

  const domainColors = useMemo(() => {
    const map = {};
    (config?.domainApplications || []).forEach((d) => {
      map[d.id] = d.color;
    });
    return map;
  }, [config]);

  const concept = conceptByKey(landscapeConcept);
  const valueOf = useCallback((d) => conceptValue(concept, d), [concept]);
  const { shapes: shapesOn } = useShapes();
  const conceptItems = useMemo(() => {
    const values = conceptValues(concept, datasets || []);
    const colors = conceptColors(concept, values, config);
    const shapes = shapesOn ? shapeMap(values) : null;
    const items = values.map((v) => ({ id: v, label: v, color: colors[v], shape: shapes?.[v] }));
    return { colors, shapes, items };
  }, [concept, datasets, config, shapesOn]);

  const chooseConcept = (key) => {
    setCatalogFilters(({ facets }) => {
      const { [key]: _, ...rest } = facets;
      return { concept: key, values: [], facets: rest };
    });
  };

  const filtered = useMemo(() => {
    if (!datasets) return [];
    return datasets.filter((d) => matchesCatalogFilters(d, catalogFilters));
  }, [datasets, catalogFilters]);

  const visibleIds = useMemo(() => new Set(filtered.map((d) => d._id)), [filtered]);

  const tileDatasets = useMemo(() => {
    if (!datasets) return [];
    return datasets.filter((d) => matchesFacetFilters(d, facetFilters) && matchesQuery(d, query));
  }, [datasets, facetFilters, query]);

  const tileItems = useMemo(() => {
    const present = new Set(tileDatasets.map(valueOf));
    return conceptItems.items.filter((item) => present.has(item.id) || selectedValues.includes(item.id));
  }, [conceptItems, tileDatasets, valueOf, selectedValues]);

  const listed = useMemo(() => {
    const list = filtered.filter((d) => !isHidden(d));
    return [...list].sort((a, b) => {
      if (Boolean(a._userAdded) !== Boolean(b._userAdded)) return a._userAdded ? -1 : 1;
      if (a._userAdded && b._userAdded) return (b._addedAt || '').localeCompare(a._addedAt || '');
      return 0;
    });
  }, [filtered]);

  const handleLogAdded = () => {
    loadDatasets().then(setDatasets);
  };

  const userEntries = datasets ? datasets.filter((d) => d._userAdded) : [];

  const toggleValue = (id) => {
    setCatalogFilters(({ values }) => ({ values: values.includes(id) ? values.filter((t) => t !== id) : [...values, id] }));
  };

  const toggleFacet = (facetKey, value) => {
    setCatalogFilters(({ facets }) => {
      const current = facets[facetKey] || [];
      const next = current.includes(value) ? current.filter((v) => v !== value) : [...current, value];
      return { facets: { ...facets, [facetKey]: next } };
    });
  };

  const clearAllFilters = clearCatalogFilters;

  const hasActiveFilters =
    selectedValues.length > 0 || query || Object.values(facetFilters).some((v) => v && v.length > 0);

  if (!datasets || !config) {
    return (
      <div className="main-layout">
        <div className="loading">
          <div className="loading__spinner" />
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  const labels = config.visualization?.labels || {};

  return (
    <div className="main-layout">
      <Header config={config} />
      <main className="main-content">
        <div className="papers-layout">
          <div className="papers-layout__main">
            <section className="contribute-cta">
              <div className="contribute-cta__text">
                <h2 className="contribute-cta__title">{labels.contributeTitle || 'Add your event data to the landscape'}</h2>
                <p>
                  {labels.contributeText ||
                    'Every event dataset you add widens what we know about event data. Load XES, XES YAML or CSV files: the features are computed in your browser, and only the metadata is sent if you choose to.'}
                </p>
              </div>
              <div className="contribute-cta__actions">
                <button type="button" className="btn btn--primary btn--lg" onClick={() => setShowAddLog(true)}>
                  + Add Event Data
                </button>
                {userEntries.length > 0 && (
                  <button type="button" className="btn btn--secondary" onClick={() => setSendKeys([])}>
                    Send your entries ({userEntries.length})
                  </button>
                )}
              </div>
            </section>

            {config.features?.stats !== false && <StatsBar datasets={filtered} />}

            <DomainApplicationsOverview
              items={tileItems}
              valueOf={valueOf}
              datasets={tileDatasets}
              selected={selectedValues}
              onToggle={toggleValue}
              title={concept.key === 'domain_application' ? labels.domainsTitle || 'Domain Applications' : concept.label}
              hint={labels.domainsHint}
              control={<ConceptSelect id="landscape-concept" label="Concept" value={landscapeConcept} onChange={chooseConcept} />}
            />

            {config.features?.landscape !== false && (
              <section className="landscape-section">
                <div className="landscape-section__head">
                  <h2 className="detail-section__title">{labels.landscapeTitle || 'Event Dataset Landscape'}</h2>
                  <ShapesToggle />
                </div>
                {labels.landscapeDescription && <p className="graph-page__description">{labels.landscapeDescription}</p>}
                <LandscapeVisualization
                  datasets={datasets}
                  visible={visibleIds}
                  concept={concept}
                  colors={conceptItems.colors}
                  shapes={conceptItems.shapes}
                />
              </section>
            )}

            <div className="toolbar">
              {config.features?.search !== false && (
                <input
                  type="search"
                  placeholder="Search event datasets by name, domain, or reference…"
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                  className="toolbar__search"
                />
              )}
              {config.features?.filters !== false && (
                <button
                  type="button"
                  className={`btn ${showFilters ? 'btn--primary' : 'btn--secondary'}`}
                  onClick={() => setShowFilters((v) => !v)}
                >
                  Filters
                </button>
              )}
              {hasActiveFilters && (
                <button type="button" className="btn btn--ghost" onClick={clearAllFilters}>
                  Clear filters
                </button>
              )}
            </div>

            {showFilters && config.features?.filters !== false && (
              <FiltersPanel
                datasets={datasets}
                filters={facetFilters}
                onToggle={toggleFacet}
                onClear={() => setCatalogFilters({ facets: {} })}
                exclude={landscapeConcept}
              />
            )}
          </div>

          <div className="papers-layout__sidebar">
            <p className="results-count">
              {listed.length} {listed.length === 1 ? labels.entrySingular || 'event dataset' : labels.entryPlural || 'event datasets'}
              {filtered.length > listed.length &&
                ` listed, plus ${filtered.length - listed.length} hidden ones that only count in the tiles and plots, as their names and sources are not public yet.`}
            </p>

            {listed.length === 0 ? (
              <div className="empty-state">
                <p>No event datasets match the current filters.</p>
              </div>
            ) : (
              <div className="log-list">
                {listed.map((dataset) => (
                  <EventLogCard key={dataset._id} dataset={dataset} domainColors={domainColors} />
                ))}
              </div>
            )}
          </div>
        </div>
      </main>

      {showAddLog && (
        <AddEventLogModal
          config={config}
          datasets={datasets}
          onClose={() => setShowAddLog(false)}
          onAdded={handleLogAdded}
        />
      )}

      {sendKeys && (
        <SendEntriesModal
          config={config}
          datasets={datasets}
          initialKeys={sendKeys}
          onClose={() => setSendKeys(null)}
          onSent={setDatasets}
        />
      )}
    </div>
  );
}
