const EOCD = 0x06054b50;
const EOCD64_LOCATOR = 0x07064b50;
const CENTRAL = 0x02014b50;
const LOCAL = 0x04034b50;

async function bytes(file, start, end) {
  return new DataView(await file.slice(start, end).arrayBuffer());
}

function readName(view, offset, length) {
  return new TextDecoder().decode(new Uint8Array(view.buffer, view.byteOffset + offset, length));
}

export async function listZipEntries(file) {
  const tailStart = Math.max(0, file.size - 65557);
  const tail = await bytes(file, tailStart, file.size);
  let eocd = -1;
  for (let i = tail.byteLength - 22; i >= 0; i -= 1) {
    if (tail.getUint32(i, true) === EOCD) {
      eocd = i;
      break;
    }
  }
  if (eocd < 0) throw new Error('This is not a readable .zip file.');
  let count = tail.getUint16(eocd + 10, true);
  let cdSize = tail.getUint32(eocd + 12, true);
  let cdOffset = tail.getUint32(eocd + 16, true);
  if (eocd >= 20 && tail.getUint32(eocd - 20, true) === EOCD64_LOCATOR) {
    const eocd64Offset = Number(tail.getBigUint64(eocd - 12, true));
    const eocd64 = await bytes(file, eocd64Offset, eocd64Offset + 56);
    count = Number(eocd64.getBigUint64(32, true));
    cdSize = Number(eocd64.getBigUint64(40, true));
    cdOffset = Number(eocd64.getBigUint64(48, true));
  }
  const cd = await bytes(file, cdOffset, cdOffset + cdSize);
  const entries = [];
  let p = 0;
  for (let n = 0; n < count && p + 46 <= cd.byteLength; n += 1) {
    if (cd.getUint32(p, true) !== CENTRAL) throw new Error('The .zip file is damaged.');
    const method = cd.getUint16(p + 10, true);
    let compressedSize = cd.getUint32(p + 20, true);
    let size = cd.getUint32(p + 24, true);
    const nameLength = cd.getUint16(p + 28, true);
    const extraLength = cd.getUint16(p + 30, true);
    const commentLength = cd.getUint16(p + 32, true);
    let localOffset = cd.getUint32(p + 42, true);
    const name = readName(cd, p + 46, nameLength);
    let e = p + 46 + nameLength;
    const extraEnd = e + extraLength;
    while (e + 4 <= extraEnd) {
      const id = cd.getUint16(e, true);
      const length = cd.getUint16(e + 2, true);
      if (id === 0x0001) {
        let q = e + 4;
        if (size === 0xffffffff) {
          size = Number(cd.getBigUint64(q, true));
          q += 8;
        }
        if (compressedSize === 0xffffffff) {
          compressedSize = Number(cd.getBigUint64(q, true));
          q += 8;
        }
        if (localOffset === 0xffffffff) localOffset = Number(cd.getBigUint64(q, true));
      }
      e += 4 + length;
    }
    if (!name.endsWith('/')) entries.push({ name, method, compressedSize, size, localOffset });
    p = extraEnd + commentLength;
  }
  return entries;
}

export async function readZipEntryText(file, entry) {
  const local = await bytes(file, entry.localOffset, entry.localOffset + 30);
  if (local.getUint32(0, true) !== LOCAL) throw new Error(`The .zip file is damaged at ${entry.name}.`);
  const start = entry.localOffset + 30 + local.getUint16(26, true) + local.getUint16(28, true);
  const blob = file.slice(start, start + entry.compressedSize);
  if (entry.method === 0) return blob.text();
  if (entry.method !== 8) throw new Error(`${entry.name} is packed in a way this page cannot unpack.`);
  if (typeof DecompressionStream === 'undefined') {
    throw new Error('This browser cannot unpack .zip files. Please unpack the archive and choose the files.');
  }
  return new Response(blob.stream().pipeThrough(new DecompressionStream('deflate-raw'))).text();
}
