import { createContext, useCallback, useContext, useState } from 'react';
import * as d3 from 'd3';

const STORAGE_KEY = 'xespresso:shapes';

export const SHAPES = [
  'circle',
  'square',
  'triangle',
  'diamond',
  'star',
  'cross',
  'wye',
  'triangleDown',
  'pentagon',
  'hexagon',
  'times',
  'triangleRight',
  'triangleLeft',
];

const rotated = (symbol, angle) => ({
  draw(context, size) {
    const c = Math.cos(angle);
    const s = Math.sin(angle);
    symbol.draw(
      {
        moveTo: (x, y) => context.moveTo(x * c - y * s, x * s + y * c),
        lineTo: (x, y) => context.lineTo(x * c - y * s, x * s + y * c),
        closePath: () => context.closePath(),
      },
      size
    );
  },
});

const polygon = (sides, rotation) => ({
  draw(context, size) {
    const r = Math.sqrt(size / ((sides / 2) * Math.sin((2 * Math.PI) / sides)));
    for (let i = 0; i < sides; i += 1) {
      const a = rotation + (2 * Math.PI * i) / sides;
      if (i === 0) context.moveTo(r * Math.cos(a), r * Math.sin(a));
      else context.lineTo(r * Math.cos(a), r * Math.sin(a));
    }
    context.closePath();
  },
});

const SYMBOLS = {
  circle: d3.symbolCircle,
  square: d3.symbolSquare,
  triangle: d3.symbolTriangle,
  diamond: d3.symbolDiamond,
  star: d3.symbolStar,
  cross: d3.symbolCross,
  wye: d3.symbolWye,
  triangleDown: polygon(3, Math.PI / 2),
  pentagon: polygon(5, -Math.PI / 2),
  hexagon: polygon(6, 0),
  times: rotated(d3.symbolCross, Math.PI / 4),
  triangleRight: polygon(3, 0),
  triangleLeft: polygon(3, Math.PI),
};

const AREA_SCALE = {
  circle: 1,
  square: 0.85,
  triangle: 1.2,
  diamond: 0.9,
  star: 1.3,
  cross: 1.1,
  wye: 1.3,
  triangleDown: 1.2,
  pentagon: 1,
  hexagon: 1,
  times: 1.1,
  triangleRight: 1.2,
  triangleLeft: 1.2,
};

export const shapeAt = (index) => SHAPES[index % SHAPES.length];

export function shapeMap(values) {
  return Object.fromEntries(values.map((v, i) => [v, shapeAt(i)]));
}

export function shapePath(shape, radius) {
  const name = SYMBOLS[shape] ? shape : 'circle';
  return d3.symbol().type(SYMBOLS[name]).size(Math.PI * radius * radius * AREA_SCALE[name])();
}

function readStored() {
  try {
    return localStorage.getItem(STORAGE_KEY) === 'on';
  } catch {
    return false;
  }
}

const ShapesContext = createContext({ shapes: false, setShapes: () => {} });

export function ShapesProvider({ children }) {
  const [shapes, setShapesState] = useState(readStored);
  const setShapes = useCallback((on) => {
    setShapesState(on);
    try {
      localStorage.setItem(STORAGE_KEY, on ? 'on' : 'off');
    } catch {
      return;
    }
  }, []);
  return <ShapesContext.Provider value={{ shapes, setShapes }}>{children}</ShapesContext.Provider>;
}

export const useShapes = () => useContext(ShapesContext);

export function ShapesToggle() {
  const { shapes, setShapes } = useShapes();
  return (
    <label
      className="add-log__check concept-controls__check"
      title="Give each value a shape as well as a colour, so it can be told apart without colour"
    >
      <input type="checkbox" checked={shapes} onChange={(e) => setShapes(e.target.checked)} />
      <span>Distinguish by Shape</span>
    </label>
  );
}

export function ShapeIcon({ shape, color, size = 12 }) {
  const r = size / 2;
  return (
    <svg width={size} height={size} viewBox={`${-r} ${-r} ${size} ${size}`} aria-hidden="true" focusable="false">
      <path d={shapePath(shape, r * 0.8)} fill={color} />
    </svg>
  );
}
