import { useState } from 'react';
import FiltersPanel from '@/components/FiltersPanel';
import { FACETS } from '@/lib/filters';
import { conceptByKey } from '@/lib/concepts';
import { clearCatalogFilters, hasCatalogFilters, setCatalogFilters, useCatalogFilters } from '@/lib/catalogFilters';

const toggleFacet = (facetKey, value) =>
  setCatalogFilters(({ facets }) => {
    const selected = facets[facetKey] || [];
    return {
      facets: { ...facets, [facetKey]: selected.includes(value) ? selected.filter((v) => v !== value) : [...selected, value] },
    };
  });

/**
 * The filters shared by all pages: a toggle for the facet panel, a summary and a clear button.
 * `hide` lists facets this page offers no control for; selections made for them elsewhere still apply and are named.
 */
export default function SharedFiltersBar({ datasets, summary, hide = [] }) {
  const [open, setOpen] = useState(false);
  const filters = useCatalogFilters();
  const active = hasCatalogFilters(filters);
  const hiddenSelections = FACETS.filter((f) => hide.includes(f.key) && filters.facets[f.key]?.length > 0);
  const query = (filters.query || '').trim();

  return (
    <>
      <div className="concept-controls space-filters">
        <button type="button" className={`btn btn--sm ${open ? 'btn--primary' : 'btn--secondary'}`} onClick={() => setOpen((v) => !v)}>
          Filters
        </button>
        <span className="space-filters__summary">{summary} The filters are shared by all pages.</span>
        {active && (
          <button type="button" className="btn btn--ghost btn--sm" onClick={clearCatalogFilters}>
            Clear filters
          </button>
        )}
      </div>
      {(filters.values.length > 0 || query || hiddenSelections.length > 0) && (
        <p className="add-log__hint">
          Also applied, from the catalog:{' '}
          {[
            filters.values.length > 0 && `${conceptByKey(filters.concept).label} is ${filters.values.join(' or ')}`,
            query && `search "${query}"`,
            ...hiddenSelections.map((f) => `${f.label} is ${filters.facets[f.key].join(' or ')}`),
          ]
            .filter(Boolean)
            .join('; ')}
          .
        </p>
      )}
      {open && (
        <FiltersPanel
          datasets={datasets}
          filters={filters.facets}
          onToggle={toggleFacet}
          onClear={() => setCatalogFilters({ facets: {} })}
          exclude={filters.values.length > 0 ? filters.concept : undefined}
          hide={hide}
        />
      )}
    </>
  );
}
